const item = $input.first().json;
const platform = item.platform || item.body?.platform || 'Twitter / X';
const author = item.author_handle || item.body?.author_handle || '@tech_influencer_pro';
const followers = item.follower_count || item.body?.follower_count || 85000;
const text = item.post_content || item.body?.post_content || '';
const url = item.post_url || item.body?.post_url || 'https://x.com';

const prMatrix = `Crisis Matrix Guidelines:
- P0_CRITICAL_EMERGENCY (urgency >= 75): Security vulnerability claims, active data breach allegations, legal threats, or viral influencers (>20k followers) spreading severe reputational damage.
- P1_MODERATE_RISK (urgency >= 40): Outage reports, pricing backlash, angry paying customer feedback.
- P2_POSITIVE_NEUTRAL (urgency < 40): Praise, product reviews, feature suggestions, general community chatter.`;

return [{
  json: {
    platform: platform,
    author_handle: author,
    follower_count: followers,
    post_content: text,
    post_url: url,
    pr_guidelines: prMatrix
  }
}];

