📝 **Crisis Summary:**
${data.crisis_summary}

⚠️ **Allegations Detected:**
${allegations.map(a => '• ' + a).join('\n')}

🛡️ **Containment Action:**
${data.immediate_containment_action}

💬 **Drafted Public PR Response:**
"${data.draft_empathetic_public_response}"

📌 **Action:** Incident response channel #war-room-pr notified immediately.
`;

return [{
  json: {
    incident_tier: 'P0_CRITICAL_EMERGENCY',
    notification_card: emergencyCard,
    author: mention.author_handle,
    urgency_score: data.urgency_score,
    public_response_draft: data.draft_empathetic_public_response
  }
}];

